// ── Localisation helpers ──────────────────────────────────────────
async function getUserLang(env, uid) {
  try {
    const r = await dbGet(env, `users/${uid}/language`);
    return (r.data && ['ar','en','ru','es','fr'].includes(r.data)) ? r.data : 'en';
  } catch (_) { return 'en'; }
}
function m(key, lang, ...args) {
  const variants = MSG[key]; if (!variants) return '';
  const fn = variants[lang] || variants['en'];
  return fn ? fn(...args) : '';
}

// ── Telegram notifications ────────────────────────────────────────
async function sendTgNotification(env, userId, message) {
  try {
    if (!env.BOT_TOKEN || !userId) return;
    await fetch(`https://api.telegram.org/bot${env.BOT_TOKEN}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: String(userId), text: message, parse_mode: 'HTML' }),
    });
  } catch (e) { console.error('sendTgNotification:', e.message); }
}

// ── HTTP helpers ──────────────────────────────────────────────────
const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Action',
  'Access-Control-Max-Age': '86400',
};
const JSON_CT = { 'Content-Type': 'application/json', ...CORS };
const jRes  = (b, s=200) => new Response(JSON.stringify(b), { status: s, headers: JSON_CT });
const ok    = (d)        => jRes({ success: true, data: d });
const fail  = (msg, s=400) => jRes({ success: false, error: msg }, s);

function sanitise(i) {
  if (!i) return i;
  return i.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
          .replace(/[<>]/g, c => c === '<' ? '&lt;' : '&gt;');
}

// ── Firebase helpers ──────────────────────────────────────────────
function fbUrl(env, path) {
  const b = env.FIREBASE_DATABASE_URL?.replace(/\/$/, '');
  if (!b) throw new Error('FIREBASE_DATABASE_URL not set');
  const k = env.FIREBASE_API_KEY;
  if (!k) throw new Error('FIREBASE_API_KEY not set');
  return `${b}/${path.replace(/^\//, '')}.json?key=${k}`;
}
async function dbGet(env, path) {
  try {
    const r = await fetch(fbUrl(env, path));
    if (!r.ok) throw new Error(`GET ${r.status}`);
    return { success: true, data: await r.json() };
  } catch (e) { console.error('DB GET', path, e.message); return { success: false, error: e.message }; }
}
async function dbSet(env, path, data) {
  try {
    const r = await fetch(fbUrl(env, path), { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
    if (!r.ok) throw new Error(`SET ${r.status}`);
    return { success: true };
  } catch (e) { console.error('DB SET', path, e.message); return { success: false, error: e.message }; }
}
async function dbUpdate(env, path, updates) {
  try {
    const r = await fetch(fbUrl(env, path), { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(updates) });
    if (!r.ok) throw new Error(`UPDATE ${r.status}`);
    return { success: true };
  } catch (e) { console.error('DB UPDATE', path, e.message); return { success: false, error: e.message }; }
}
async function dbPush(env, path, data) {
  try {
    const r = await fetch(fbUrl(env, path), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
    if (!r.ok) throw new Error(`PUSH ${r.status}`);
    const j = await r.json();
    return { success: true, data: { id: j.name } };
  } catch (e) { console.error('DB PUSH', path, e.message); return { success: false, error: e.message }; }
}
async function dbDelete(env, path) {
  try {
    const r = await fetch(fbUrl(env, path), { method: 'DELETE' });
    if (!r.ok) throw new Error(`DELETE ${r.status}`);
    return { success: true };
  } catch (e) { console.error('DB DELETE', path, e.message); return { success: false, error: e.message }; }
}

// ── Rate limiters ─────────────────────────────────────────────────
const _rl = new Map();
function rateOk(ip) {
  const now = Date.now();
  const d   = _rl.get(ip) || { c: 0, r: now + 60000 };
  if (now > d.r) { d.c = 0; d.r = now + 60000; }
  d.c++;
  _rl.set(ip, d);
  return d.c <= 60;
}

const _userActionTs = new Map();
const ACTION_COOLDOWNS = {
  withdraw: 5000,
  deposit:  2500,
  claimTask: 2500,
  verifyTask: 2500,
  saveLanguage: 2000,
};
function userActionOk(uid, action) {
  const cd = ACTION_COOLDOWNS[action];
  if (!cd) return true;
  const key  = `${uid}:${action}`;
  const now  = Date.now();
  const last = _userActionTs.get(key) || 0;
  if (now - last < cd) return false;
  _userActionTs.set(key, now);
  return true;
}

// ── Balance logging ───────────────────────────────────────────────
const BALANCE_CHANGE_EVENTS = new Set([
  'withdraw_request', 'deposit_completed', 'claim_task',
  'admin_set_balance', 'admin_confirm_deposit', 'referral_commission',
]);
function log(env, uid, type, details = {}, meta = {}) {
  if (!BALANCE_CHANGE_EVENTS.has(type)) return;
  const ts   = Date.now();
  const date = new Date(ts).toISOString();
  const entry = { ts, date, type, ...details };
  dbPush(env, `users/${uid}/log`, entry).catch(e => console.error('LOG ERROR:', e.message));
}

// ── Telegram initData validation ──────────────────────────────────
async function validateTg(initData, botToken) {
  try {
    if (!initData) return { valid: false, error: 'No init data' };
    const p = new URLSearchParams(initData);
    const startParam = (p.get('start_param') || '').replace(/\D/g, '');
    if (!botToken) {
      const u = p.get('user');
      if (!u) return { valid: false, error: 'No user' };
      return { valid: true, user: JSON.parse(decodeURIComponent(u)), startParam };
    }
    const hash = p.get('hash');
    if (!hash) return { valid: false, error: 'No hash' };
    p.delete('hash');
    const authDate = parseInt(p.get('auth_date') || '0');
    if (Date.now() / 1000 - authDate > 900) return { valid: false, error: 'Expired' };
    const dc  = [...p.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([k, v]) => `${k}=${v}`).join('\n');
    const enc = new TextEncoder();
    const sec = await crypto.subtle.importKey('raw', enc.encode('WebAppData'), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const kb  = await crypto.subtle.sign('HMAC', sec, enc.encode(botToken));
    const key = await crypto.subtle.importKey('raw', kb, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const sig = await crypto.subtle.sign('HMAC', key, enc.encode(dc));
    const hex = [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, '0')).join('');
    if (hex !== hash) return { valid: false, error: 'Bad hash' };
    const u = p.get('user');
    if (!u) return { valid: false, error: 'No user' };
    return { valid: true, user: JSON.parse(decodeURIComponent(u)), startParam };
  } catch (e) { return { valid: false, error: e.message }; }
}

function extractStartParam(initDataStr) {
  try {
    const p  = new URLSearchParams(initDataStr || '');
    const sp = p.get('start_param');
    if (sp) return sp.replace(/\D/g, '');
    const userRaw = p.get('user');
    if (userRaw) {
      const u = JSON.parse(decodeURIComponent(userRaw));
      if (u.start_param) return String(u.start_param).replace(/\D/g, '');
    }
  } catch (_) {}
  return '';
}

// ── Referral registration ─────────────────────────────────────────
async function registerReferral(env, uid, user, referrerId, ctx) {
  try {
    const rr   = await dbGet(env, `users/${referrerId}/referrals`);
    const refs = rr.data || {};
    if (!refs[uid]) {
      await dbSet(env, `users/${referrerId}/referrals/${uid}`, {
        userId:    uid,
        firstName: user.firstName,
        lastName:  user.lastName,
        username:  user.username,
        photoUrl:  user.photoUrl,
        joinedAt:  Date.now(),
        earned:    0,
        hasWithdrawn: false,
        hasDeposited: false,
      });
      // Send notification once
      const notifKey = `notifSent/ref_${uid}_${referrerId}`;
      const already  = await dbGet(env, notifKey);
      if (!already.data) {
        const myTs   = Date.now();
        await dbSet(env, notifKey, { ts: myTs, by: uid });
        await new Promise(r => setTimeout(r, 150));
        const confirm = await dbGet(env, notifKey);
        if (confirm.data && confirm.data.ts === myTs) {
          const refName = (user.firstName || 'Someone').slice(0, 32);
          const refLang = await getUserLang(env, referrerId);
          if (ctx && ctx.waitUntil)
            ctx.waitUntil((async () => {
              await sendTgNotification(env, referrerId, m('ref_joined', refLang, refName));
            })().catch(() => {}));
        }
      }
    }
  } catch (e) { console.error('registerReferral:', e.message); }
}

// ── User factory ──────────────────────────────────────────────────
function makeUser(uid, tg = {}, ref = null) {
  return {
    userId:       uid,
    firstName:    (tg.first_name || '').slice(0, 64),
    lastName:     (tg.last_name  || '').slice(0, 64),
    username:     (tg.username   || '').slice(0, 64),
    photoUrl:     (tg.photo_url  || '').slice(0, 512),
    tonBalance:   0,
    hasDeposited: false,
    hasWithdrawn: false,
    referralCode: String(uid),
    referredBy:   ref || null,
    completedTasks: [],
    withdrawWallet: null,
    createdAt:    Date.now(),
    language:     'en',
  };
}

// ── getState ──────────────────────────────────────────────────────
async function hGetState(env, uid, tg, data = {}, _meta = {}, ctx = null) {
  try {
    const rawRef = (
      data?._startParam ||
      extractStartParam(data?._initData || '') ||
      (data?.start_param || '').toString().replace(/\D/g, '')
    ).replace(/\D/g, '');
    const ref = rawRef && rawRef !== uid ? rawRef : null;

    const ur   = await dbGet(env, `users/${uid}`);
    let user   = ur.data;

    if (!user) {
      // New user
      user = makeUser(uid, tg, ref);
      if (user.referredBy) await registerReferral(env, uid, user, user.referredBy, ctx);
      await dbSet(env, `users/${uid}`, user);
      // Welcome notification
      if (ctx && ctx.waitUntil)
        ctx.waitUntil((async () => {
          const wl = (tg?.language_code && ['ar','en','ru','es','fr'].includes(tg.language_code))
            ? tg.language_code : 'en';
          await sendTgNotification(env, uid, m('welcome', wl, G.MIN_WITHDRAW_TON));
        })().catch(() => {}));
    } else {
      // Update profile info from Telegram
      if (tg) {
        const profileUpdates = {};
        if (tg.first_name) profileUpdates.firstName = tg.first_name.slice(0, 64);
        if (tg.last_name)  profileUpdates.lastName  = tg.last_name.slice(0, 64);
        if (tg.username)   profileUpdates.username  = tg.username.slice(0, 64);
        if (tg.photo_url)  profileUpdates.photoUrl  = tg.photo_url.slice(0, 512);
        if (Object.keys(profileUpdates).length)
          await dbUpdate(env, `users/${uid}`, profileUpdates).catch(() => {});
        Object.assign(user, profileUpdates);
      }
    }

    // Fetch referrals
    const rr      = await dbGet(env, `users/${uid}/referrals`);
    const refList  = Object.values(rr.data || {});
    const referrals = await Promise.all(refList.map(async r => {
      let hasWithdrawn = r.hasWithdrawn || false;
      let hasDeposited = r.hasDeposited || false;
      if (!hasWithdrawn) {
        const ud = await dbGet(env, `users/${r.userId}/hasWithdrawn`);
        hasWithdrawn = ud.data === true;
        if (hasWithdrawn)
          await dbUpdate(env, `users/${uid}/referrals/${r.userId}`, { hasWithdrawn: true }).catch(() => {});
      }
      if (!hasDeposited) {
        const ud = await dbGet(env, `users/${r.userId}/hasDeposited`);
        hasDeposited = ud.data === true;
        if (hasDeposited)
          await dbUpdate(env, `users/${uid}/referrals/${r.userId}`, { hasDeposited: true }).catch(() => {});
      }
      const isActive = hasWithdrawn || hasDeposited;
      return {
        userId:       r.userId,
        name:         `${r.firstName || ''} ${r.lastName || ''}`.trim() || 'Friend',
        photo:        r.photoUrl || null,
        date:         r.joinedAt ? new Date(r.joinedAt).toLocaleDateString() : '',
        earned:       r.earned   || 0,
        hasWithdrawn: isActive,
        hasDeposited: isActive,
      };
    }));

    // Withdrawal history
    const wr         = await dbGet(env, `users/${uid}/wdHistory`);
    const wdHistory  = wr.data ? Object.values(wr.data).sort((a, b) => b.ts - a.ts).slice(0, 10) : [];

    // Balance log
    const lr         = await dbGet(env, `users/${uid}/log`);
    const balanceLog = lr.data
      ? Object.values(lr.data).sort((a, b) => b.ts - a.ts).slice(0, 20)
          .map(e => ({ ts: e.ts, type: e.type, amount: e.amount, balance: e.balance }))
      : [];

    // Deposit history
    const dr          = await dbGet(env, `users/${uid}/deposits`);
    const depositHistory = dr.data ? Object.values(dr.data).sort((a, b) => b.ts - a.ts).slice(0, 10) : [];

    return {
      success: true,
      data: {
        user: {
          tonBalance:    user.tonBalance    || 0,
          hasDeposited:  user.hasDeposited  || false,
          hasWithdrawn:  user.hasWithdrawn  || false,
          withdrawWallet: user.withdrawWallet || null,
          firstName:     user.firstName     || '',
          lastName:      user.lastName      || '',
          username:      user.username      || '',
          photoUrl:      user.photoUrl      || '',
          referralCode:  user.referralCode  || uid,
          referredBy:    user.referredBy    || null,
          language:      user.language      || 'en',
          completedTasks: user.completedTasks || [],
        },
        referrals,
        wdHistory,
        depositHistory,
        balanceLog,
      },
    };
  } catch (e) {
    console.error('getState', e);
    return { success: false, error: e.message, errorCode: 'GET_STATE_ERROR' };
  }
}

// ── Deposit ───────────────────────────────────────────────────────
async function hDeposit(env, uid, data, _meta = {}) {
  try {
    const amt    = parseFloat(data.amount) || 0;
    const txHash = (data.txHash || '').slice(0, 256);
    if (!txHash || amt < G.MIN_DEPOSIT_TON)
      return { success: false, error: `Invalid deposit. Minimum is ${G.MIN_DEPOSIT_TON} TON.` };

    // Duplicate transaction guard
    const safeHash = txHash.replace(/[^a-zA-Z0-9]/g, '_');
    const dup      = await dbGet(env, `txHashes/${safeHash}`);
    if (dup.data) return { success: false, error: 'Duplicate transaction' };

    const depId = `dep_${uid}_${Date.now()}`;
    const rec   = { depId, userId: uid, txHash, amount: amt, status: 'pending', ts: Date.now() };
    await dbSet(env, `users/${uid}/deposits/${depId}`, rec);
    await dbSet(env, `pendingDeposits/${depId}`, rec);
    await dbSet(env, `txHashes/${safeHash}`, { depId, userId: uid, ts: Date.now() });
    return {
      success: true,
      data: {
        depositId: depId,
        message:   'Transaction registered. Your TON balance will be added within 3 minutes.',
      },
    };
  } catch (e) { return { success: false, error: e.message }; }
}

// ── Withdraw ──────────────────────────────────────────────────────
async function hWithdraw(env, uid, data, _meta = {}) {
  try {
    const addr = (data.address || '').trim();
    const amt  = parseFloat(data.amount) || 0;
    if (!addr || addr.length < 10) return { success: false, error: 'Invalid TON address' };
    if (amt < G.MIN_WITHDRAW_TON)
      return { success: false, error: `Minimum withdrawal is ${G.MIN_WITHDRAW_TON} TON` };
    if (amt > 100000) return { success: false, error: 'Amount too large' };

    // Wallet uniqueness check (prevent multi-account abuse)
    const safeAddr  = addr.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 120);
    const addrRec   = await dbGet(env, `walletAddresses/${safeAddr}`);
    if (addrRec.data && addrRec.data.uid && addrRec.data.uid !== uid)
      return { success: false, error: 'WALLET_USED', errorCode: 'WALLET_USED' };

    // 60-second lock to prevent concurrent withdrawals
    const lockKey = `withdrawLocks/${uid}`;
    const lockRec = await dbGet(env, lockKey);
    const now     = Date.now();
    if (lockRec.data && (now - (lockRec.data.ts || 0)) < 60000)
      return { success: false, error: 'A withdrawal is already being processed. Please wait 60 seconds.' };
    await dbSet(env, lockKey, { ts: now, uid });

    try {
      const r    = await dbGet(env, `users/${uid}`);
      const user = r.data;
      if (!user) { await dbSet(env, lockKey, { ts: 0 }); return { success: false, error: 'User not found' }; }
      if ((user.tonBalance || 0) < amt) { await dbSet(env, lockKey, { ts: 0 }); return { success: false, error: 'Insufficient TON balance' }; }
      if ((now - (user._lastWdTs || 0)) < 60000) { await dbSet(env, lockKey, { ts: 0 }); return { success: false, error: 'Please wait 60 seconds before next withdrawal' }; }

      // Only one pending withdrawal at a time
      const wdHistRec  = await dbGet(env, `users/${uid}/wdHistory`);
      const hasPending = Object.values(wdHistRec.data || {}).some(w => w && w.status === 'pending');
      if (hasPending) {
        await dbSet(env, lockKey, { ts: 0 });
        return { success: false, error: 'You already have a pending withdrawal.', errorCode: 'PENDING_WITHDRAW_EXISTS' };
      }

      const wdId   = `wd_${uid}_${now}`;
      const feeAmt = parseFloat((amt * G.WITHDRAW_FEE_PCT / 100).toFixed(8));
      const netAmt = parseFloat((amt - feeAmt).toFixed(8));
      const upd    = {
        tonBalance:    parseFloat(((user.tonBalance || 0) - amt).toFixed(8)),
        _lastWdTs:     now,
        hasWithdrawn:  true,
        withdrawWallet: addr,
      };
      await dbUpdate(env, `users/${uid}`, upd);

      // Register wallet
      if (!addrRec.data) await dbSet(env, `walletAddresses/${safeAddr}`, { uid, ts: now });

      const rec = { wdId, userId: uid, address: addr, amt: netAmt, amtRequested: amt, fee: feeAmt, status: 'pending', ts: now };
      await dbSet(env, `users/${uid}/wdHistory/${wdId}`, rec);
      await dbSet(env, `withdrawQueue/${wdId}`, rec);

      // Mark referral as active
      if (user.referredBy) {
        await dbUpdate(env, `users/${user.referredBy}/referrals/${uid}`, { hasWithdrawn: true, hasDeposited: true }).catch(() => {});
      }

      log(env, uid, 'withdraw_request', {
        wdId, amount_requested: amt, fee: feeAmt, amount_net: netAmt,
        address: addr, tonBalance_before: user.tonBalance || 0, tonBalance_after: upd.tonBalance,
      }, _meta);
      await dbSet(env, lockKey, { ts: 0 });
      return { success: true, data: { wdId, tonBalance: upd.tonBalance, netAmt, feeAmt, status: 'pending' } };
    } catch (innerErr) {
      await dbSet(env, lockKey, { ts: 0 }).catch(() => {});
      throw innerErr;
    }
  } catch (e) { return { success: false, error: e.message }; }
}

// ── Claim Referral Task ───────────────────────────────────────────
async function hClaimTask(env, uid, data, _meta = {}, ctx = null) {
  try {
    const tid     = data.taskId;
    const lockKey = `taskLocks/${uid}_${tid}`;
    const lockRec = await dbGet(env, lockKey);
    const now     = Date.now();
    if (lockRec.data && (now - (lockRec.data.ts || 0)) < 30000) return { success: false, error: 'Already processing.' };
    await dbSet(env, lockKey, { ts: now });
    try {
      const r    = await dbGet(env, `users/${uid}`);
      const user = r.data;
      if (!user) { await dbSet(env, lockKey, { ts: 0 }); return { success: false, error: 'User not found' }; }
      if ((user.completedTasks || []).includes(tid)) { await dbSet(env, lockKey, { ts: 0 }); return { success: false, error: 'Already claimed' }; }

      const task = G.REF_TON_TASKS[tid];
      if (!task) { await dbSet(env, lockKey, { ts: 0 }); return { success: false, error: 'Unknown task' }; }

      // Count active referrals
      const rr      = await dbGet(env, `users/${uid}/referrals`);
      const refIds  = rr.data ? Object.keys(rr.data) : [];
      let activeCount = 0;
      for (const refId of refIds) {
        const hw = await dbGet(env, `users/${refId}/hasWithdrawn`);
        const hd = await dbGet(env, `users/${refId}/hasDeposited`);
        if (hw.data === true || hd.data === true) activeCount++;
      }
      if (activeCount < task.n) {
        await dbSet(env, lockKey, { ts: 0 });
        return { success: false, error: `Need ${task.n} active referrals (you have ${activeCount})` };
      }

      const newTon = (user.tonBalance || 0) + task.ton;
      await dbUpdate(env, `users/${uid}`, {
        completedTasks: [...(user.completedTasks || []), tid],
        tonBalance:     parseFloat(newTon.toFixed(8)),
      });
      log(env, uid, 'claim_task', { taskId: tid, ton_reward: task.ton, tonBalance_before: user.tonBalance || 0, tonBalance_after: newTon }, _meta);

      const labels = { rt10:'10 Active Refs', rt50:'50 Active Refs', rt100:'100 Active Refs', rt200:'200 Active Refs', rt500:'500 Active Refs', rt1000:'1000 Active Refs' };
      if (ctx && ctx.waitUntil)
        ctx.waitUntil((async () => { const tl = await getUserLang(env, uid); await sendTgNotification(env, uid, m('task_done', tl, labels[tid] || tid, task.ton)); })().catch(() => {}));
      await dbSet(env, lockKey, { ts: 0 });
      return { success: true, data: { tonBalance: parseFloat(newTon.toFixed(8)), tonAdded: task.ton } };
    } catch (innerErr) {
      await dbSet(env, lockKey, { ts: 0 }).catch(() => {});
      throw innerErr;
    }
  } catch (e) { return { success: false, error: e.message }; }
}

// ── Admin actions ─────────────────────────────────────────────────
async function hAdmin(env, action, data, ctx = null) {
  switch (action) {
    case 'adminGetUser': {
      const r = await dbGet(env, `users/${data.userId}`);
      return { success: true, data: r.data || null };
    }
    case 'adminSetBalance': {
      const r = await dbGet(env, `users/${data.userId}`);
      if (!r.data) return { success: false, error: 'User not found' };
      const newBal = parseFloat(data.balance);
      if (isNaN(newBal)) return { success: false, error: 'Invalid balance' };
      await dbUpdate(env, `users/${data.userId}`, { tonBalance: newBal });
      log(env, data.userId, 'admin_set_balance', { newBalance: newBal, by: 'admin' });
      return { success: true, data: { tonBalance: newBal } };
    }
    case 'adminConfirmDeposit': {
      const dep = await dbGet(env, `pendingDeposits/${data.depositId}`);
      if (!dep.data) return { success: false, error: 'Deposit not found' };
      const ton = parseFloat(data.amount || dep.data.amount);
      await dbUpdate(env, `users/${data.userId}/deposits/${data.depositId}`, { status: 'completed', completedAt: Date.now() });
      const u = await dbGet(env, `users/${data.userId}`);
      if (u.data) {
        const newBal = parseFloat(((u.data.tonBalance || 0) + ton).toFixed(8));
        await dbUpdate(env, `users/${data.userId}`, { tonBalance: newBal, hasDeposited: true });
        // Referral commission on first deposit
        if (u.data.referredBy && u.data.referredBy !== data.userId) {
          const comm = parseFloat((ton * G.REF_BONUS_PCT / 100).toFixed(8));
          if (comm > 0) {
            const rr = await dbGet(env, `users/${u.data.referredBy}`);
            if (rr.data) {
              const newRefBal = parseFloat(((rr.data.tonBalance || 0) + comm).toFixed(8));
              await dbUpdate(env, `users/${u.data.referredBy}`, { tonBalance: newRefBal });
              const refEntry = await dbGet(env, `users/${u.data.referredBy}/referrals/${data.userId}`);
              const prevEarned = parseFloat((refEntry.data && refEntry.data.earned) || 0);
              if (refEntry.data)
                await dbUpdate(env, `users/${u.data.referredBy}/referrals/${data.userId}`, { earned: parseFloat((prevEarned + comm).toFixed(8)), hasDeposited: true });
              log(env, u.data.referredBy, 'referral_commission', { from: data.userId, comm, tonBalance_before: rr.data.tonBalance || 0, tonBalance_after: newRefBal });
              if (ctx && ctx.waitUntil)
                ctx.waitUntil((async () => {
                  const rl = await getUserLang(env, u.data.referredBy);
                  await sendTgNotification(env, u.data.referredBy, m('ref_commission', rl, u.data.firstName || 'Friend', comm.toFixed(4), newRefBal.toFixed(4)));
                })().catch(() => {}));
            }
          }
        }
        if (u.data.referredBy)
          await dbUpdate(env, `users/${u.data.referredBy}/referrals/${data.userId}`, { hasDeposited: true }).catch(() => {});
      }
      await dbDelete(env, `pendingDeposits/${data.depositId}`);
      log(env, data.userId, 'admin_confirm_deposit', { depositId: data.depositId, amount_ton: ton, by: 'admin' });
      return { success: true, data: { tonAdded: ton } };
    }
    case 'adminApproveWithdraw': {
      const r = await dbGet(env, `withdrawQueue/${data.wdId}`);
      if (!r.data) return { success: false, error: 'Not found' };
      await dbUpdate(env, `withdrawQueue/${data.wdId}`, { status: 'approved' });
      await dbUpdate(env, `users/${r.data.userId}/wdHistory/${data.wdId}`, { status: 'approved' });
      if (ctx && ctx.waitUntil)
        ctx.waitUntil((async () => { const wdl = await getUserLang(env, r.data.userId); await sendTgNotification(env, r.data.userId, m('wd_approved', wdl, r.data.amt)); })().catch(() => {}));
      return { success: true };
    }
    case 'adminRejectWithdraw': {
      const r = await dbGet(env, `withdrawQueue/${data.wdId}`);
      if (!r.data) return { success: false, error: 'Not found' };
      await dbUpdate(env, `withdrawQueue/${data.wdId}`, { status: 'rejected' });
      await dbUpdate(env, `users/${r.data.userId}/wdHistory/${data.wdId}`, { status: 'rejected' });
      const u = await dbGet(env, `users/${r.data.userId}`);
      if (u.data) await dbUpdate(env, `users/${r.data.userId}`, { tonBalance: (u.data.tonBalance || 0) + r.data.amt });
      if (ctx && ctx.waitUntil)
        ctx.waitUntil((async () => { const rjl = await getUserLang(env, r.data.userId); await sendTgNotification(env, r.data.userId, m('wd_rejected', rjl, r.data.amt)); })().catch(() => {}));
      return { success: true };
    }
    case 'adminGetQueue': {
      const q = await dbGet(env, 'withdrawQueue');
      return { success: true, data: q.data || {} };
    }
    case 'adminGetPendingDeposits': {
      const q = await dbGet(env, 'pendingDeposits');
      return { success: true, data: q.data || {} };
    }
    default:
      return { success: false, error: 'Unknown admin action' };
  }
}

// ── Main handler ──────────────────────────────────────────────────
export default {
  async fetch(request, env, ctx) {
    if (request.method === 'OPTIONS') return new Response(null, { headers: CORS });

    const url  = new URL(request.url);
    const path = url.pathname;

    if (path === '/health')
      return ok({ status: 'ok', ts: Date.now(), env: env.ENVIRONMENT || 'production' });

    if (path === '/tonconnect-manifest.json')
      return jRes({
        url:         'https://t.me/YourBotHere',
        name:        'Project',
        iconUrl:     '',
        description: 'Deposit · Withdraw · Refer',
      });

    if (path !== '/api' || request.method !== 'POST') return fail('Not found', 404);

    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    if (!rateOk(ip)) return fail('Rate limit exceeded', 429);

    let body;
    try {
      const raw = await request.text();
      if (raw.length > 10240) return fail('Payload too large', 413);
      body = JSON.parse(sanitise(raw));
    } catch (_) { return fail('Invalid JSON', 400); }

    const authHeader = request.headers.get('Authorization') || '';
    const action     = request.headers.get('X-Action') || body.action;
    const data       = body.data || {};
    if (!action) return fail('Missing action', 400);

    // ── Admin routes ──
    const ADMIN_ACTIONS = new Set([
      'adminGetUser', 'adminSetBalance', 'adminConfirmDeposit',
      'adminApproveWithdraw', 'adminRejectWithdraw',
      'adminGetQueue', 'adminGetPendingDeposits',
    ]);
    if (ADMIN_ACTIONS.has(action)) {
      const v = await validateTg(authHeader.replace('Telegram ', ''), env.BOT_TOKEN);
      if (!v.valid) return fail('Unauthorized', 401);
      const adminIds = (env.ADMIN_IDS || '').split(',').map(s => s.trim());
      if (!adminIds.includes(String(v.user?.id))) return fail('Forbidden', 403);
      return jRes(await hAdmin(env, action, data, ctx));
    }

    // ── Ping ──
    if (action === 'ping') return jRes({ success: true, data: { pong: true, ts: Date.now() } });

    // ── Telegram auth required for all other routes ──
    if (!authHeader.startsWith('Telegram ')) return fail('Telegram authentication required', 401);
    const v = await validateTg(authHeader.replace('Telegram ', ''), env.BOT_TOKEN);
    if (!v.valid) {
      console.error('TG validation failed:', v.error);
      return jRes({
        success: false,
        error:   'Invalid Telegram authentication',
        errorCode: 'INVALID_TELEGRAM_AUTH',
        debug: {
          hasInitData:          !!authHeader,
          botTokenConfigured:   !!env.BOT_TOKEN,
          environment:          env.ENVIRONMENT || 'production',
          validationError:      v.error,
        },
      }, 401);
    }

    const uid   = String(v.user.id);
    const _meta = { ip, ua: request.headers.get('User-Agent') || '' };
    console.log(`[${new Date().toISOString()}] User:${uid} Action:${action} IP:${ip}`);

    if (!userActionOk(uid, action)) return fail('Too fast. Please wait a moment.', 429);

    switch (action) {
      case 'saveLanguage': {
        const lang = (data.lang || 'en');
        if (['ar','en','ru','es','fr'].includes(lang))
          await dbSet(env, `users/${uid}/language`, lang);
        return jRes({ success: true });
      }
      case 'getState':  return jRes(await hGetState(env, uid, v.user, { ...data, _startParam: v.startParam || '' }, _meta, ctx));
      case 'deposit':   return jRes(await hDeposit(env, uid, data, _meta));
      case 'withdraw':  return jRes(await hWithdraw(env, uid, data, _meta));
      case 'claimTask': return jRes(await hClaimTask(env, uid, data, _meta, ctx));
      default:          return fail('Unknown action', 400);
    }
  },
};
